# STAGES — author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
ENV_FILE=".env.local"

banner "Leitour · Firebase setup"

stage "Criar projeto Firebase"
say "Vamos criar (ou escolher) o projeto Leitour no console."
open_url "https://console.firebase.google.com/"
step "Faça login com a Google account que vai dona do projeto."
step "Clique em Add project / Adicionar projeto."
step "Nome sugerido: leitour (ou o que preferir)."
step "Pode desligar Google Analytics se quiser simplificar."
pause "Quando o projeto estiver aberto no console, Enter."

stage "Registrar app Web"
say "O Next.js precisa das chaves do app Web."
open_url "https://console.firebase.google.com/"
step "No overview do projeto, clique no ícone Web </> (Add app)."
step "Apelido do app: leitour-web. Não precisa Firebase Hosting agora."
step "Na tela seguinte, copie os valores do objeto firebaseConfig."
ask NEXT_PUBLIC_FIREBASE_API_KEY "apiKey:"
ask NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN "authDomain:"
ask NEXT_PUBLIC_FIREBASE_PROJECT_ID "projectId:"
ask NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET "storageBucket:"
ask NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID "messagingSenderId:"
ask NEXT_PUBLIC_FIREBASE_APP_ID "appId:"
write_env NEXT_PUBLIC_FIREBASE_API_KEY "$NEXT_PUBLIC_FIREBASE_API_KEY"
write_env NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN "$NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN"
write_env NEXT_PUBLIC_FIREBASE_PROJECT_ID "$NEXT_PUBLIC_FIREBASE_PROJECT_ID"
write_env NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET "$NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET"
write_env NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID "$NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID"
write_env NEXT_PUBLIC_FIREBASE_APP_ID "$NEXT_PUBLIC_FIREBASE_APP_ID"

stage "Ativar Authentication (Email/Senha)"
say "Conta no Leitour usa email + senha."
open_url "https://console.firebase.google.com/"
step "No menu: Build → Authentication → Get started."
step "Aba Sign-in method → Email/Password → Enable → Save."
pause "Email/Password ligado? Enter."

stage "Criar Firestore"
say "Perfil e estante moram no Firestore."
open_url "https://console.firebase.google.com/"
step "Build → Firestore Database → Create database."
step "Comece em production mode (vamos colar as rules no próximo passo)."
step "Escolha uma região próxima (ex.: southamerica-east1)."
pause "Firestore criado? Enter."

stage "Colar security rules"
say "As rules do repo estão em firestore.rules — só o dono lê/escreve a própria estante."
open_url "https://console.firebase.google.com/"
step "Firestore → Rules."
step "Abra firestore.rules neste repo, copie o conteúdo e cole no editor."
step "Publish."
pause "Rules publicadas? Enter."

finish
say "Depois: npm run dev → /auth/signup → criar conta → /books → salvar na estante."